import{_ as r,a0 as p,w as l,s as c,ao as s,I as o,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"用 Portainer.io 来监控和管理 Docker 容器（1） | LCTT x X-CMD","titleTemplate":false,"description":"用 Portainer.io 来监控和管理 Docker 容器（1） | LCTT (202009) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Portainer.io 来监控和管理 Docker 容器（1） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Portainer.io 来监控和管理 Docker 容器（1） | LCTT (202009) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1","title":"用 Portainer.io 来监控和管理 Docker 容器（1）","tag":"202009","desc":""},"relativePath":"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1.md","filePath":"[post].md"}'),d={name:"202009/20190501 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-1.md"};function u(h,a,g,m,k,b){const t=p("Link");return l(),c("div",null,[a[19]||(a[19]=s(`<h1 id="用-portainer-io-来监控和管理-docker-容器-1" tabindex="-1">用 Portainer.io 来监控和管理 Docker 容器（1） <a class="header-anchor" href="#用-portainer-io-来监控和管理-docker-容器-1" aria-label="Permalink to “用 Portainer.io 来监控和管理 Docker 容器（1）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202009/20/225425zaepvexqvg7nndqv.jpg" alt=""></p><p>随着 Docker 的使用量越来越大，监控 Docker 容器正在变得更有挑战性。每天都有大量的 Docker 容器被创建，因此如何监控它们就变得非常重要。目前已经有一些内置的工具和技术，不过对它们进行配置有一些复杂。随着基于微服务的架构正在变成接下来事实上的标准，学会这种技术将为你的知识库再添一项新技能。</p><p>基于上述场景，对一种轻量、健壮的镜像管理工具的需求日益增加。Portainer.io 解决了这个问题。 Portainer.io（最新版本是 1.20.2）非常轻量，只需 2-3 个命令就可以配置好，已经在 Docker 用户中流行起来。</p><p>比起其他工具，这个工具有很多优势，其中一些如下所示：</p><ul><li>轻量（安装此工具仅需 2 到 3 个命令，与此同时安装镜像的大小在 26 M 到 30 M 之间）</li><li>健壮且易用</li><li>可用于 Docker 监控和构建</li><li>提供对 Docker 环境的详细概况</li><li>可以管理容器、镜像、网络和卷</li><li>Portainer 部署方便，仅需一个 Docker 命令（可以在任意地方运行）</li><li>可以对完整的 Docker 容器环境进行监控</li></ul><p>Portainer 同时具有以下服务：</p><ul><li>社区支持</li><li>企业支持</li><li>与合作伙伴 OEM 服务一起的专业服务</li></ul><p>Portainer 的功能和特性如下：</p><pre><code>1. 配备了漂亮的仪表盘，易于使用和监控
2. 自带大量内置模板，便于操作和创建
3. 服务支持（仅 OEM 和企业用户）
4. 对容器、镜像、网络、卷以及配置进行几乎实时的监控
5. 包含 Docker 集群监控功能
6. 功能多样的用户管理
</code></pre>`,10)),o("p",null,[a[1]||(a[1]=n("另请阅读：",-1)),e(t,{href:"https://www.linuxtechi.com/how-to-setup-docker-on-ubuntu-server-16-04/"},{default:i(()=>[...a[0]||(a[0]=[n("如何在 Ubuntu 16.04 / 18.04 LTS 版本中安装 Docker CE",-1)])]),_:1})]),a[20]||(a[20]=s(`<h3 id="如何在-ubuntu-linux-rhel-centos-系统上安装和配置-portainer-io" tabindex="-1">如何在 Ubuntu Linux / RHEL / CentOS 系统上安装和配置 Portainer.io <a class="header-anchor" href="#如何在-ubuntu-linux-rhel-centos-系统上安装和配置-portainer-io" aria-label="Permalink to “如何在 Ubuntu Linux / RHEL / CentOS 系统上安装和配置 Portainer.io”">​</a></h3><p>注意：下面的安装过程是在 Ubuntu 18.04 上完成的，但是对 RHEL 和 CentOS 同样适用，同时假设你已经在系统上安装了 Docker CE。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ lsb_release -a</span></span>
<span class="line"><span>No LSB modules are available.</span></span>
<span class="line"><span>Distributor ID: Ubuntu</span></span>
<span class="line"><span>Description:    Ubuntu 18.04 LTS</span></span>
<span class="line"><span>Release:        18.04</span></span>
<span class="line"><span>Codename:       bionic</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>为 Portainer 创建卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker volume create portainer_data</span></span>
<span class="line"><span>portainer_data</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>使用下面的 Docker 命令来运行 Portainer 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker run -d -p 9000:9000 -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer</span></span>
<span class="line"><span>Unable to find image &#39;portainer/portainer:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from portainer/portainer</span></span>
<span class="line"><span>d1e017099d17: Pull complete</span></span>
<span class="line"><span>0b1e707a06d2: Pull complete</span></span>
<span class="line"><span>Digest: sha256:d6cc2c20c0af38d8d557ab994c419c799a10fe825e4aa57fea2e2e507a13747d</span></span>
<span class="line"><span>Status: Downloaded newer image for portainer/portainer:latest</span></span>
<span class="line"><span>35286de9f2e21d197309575bb52b5599fec24d4f373cc27210d98abc60244107</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>安装完成之后，通过主机或 Docker 的 IP 加上 Docker 引擎使用的 9000 端口在浏览器中打开 Portainer。</p><p>注意：如果 Docker 所在主机的系统防火墙开启，需要确保 9000 端口被放行，否则浏览器页面将无法打开。</p><p>在我这边，我的 Docker 主机/引擎的 IP 是 <code>192.168.1.16</code>，所以 URL 就是 <code>http://192.168.1.16:9000</code></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Login-User-Name-Password-1024x681.jpg" alt="Portainer-Login-User-Name-Password"></p><p>在创建管理员用户时，请确保密码是 8 个字符，同时用户名为 <code>admin</code>，然后点击 “Create User”。</p><p>接下来进入如下所示的页面，选中 “Local” 矩形框。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Connect-Portainer-Local-Docker-1024x538.jpg" alt="Connect-Portainer-Local-Docker"></p><p>点击 “Connect”，</p><p>可以看到 admin 用户的漂亮首页如下所示，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-Docker-Monitor-Dashboard-1024x544.jpg" alt="Portainer-io-Docker-Monitor-Dashboard"></p><p>现在 Portainer 已经准备好运行和管理你的 Docker 容器了，同时也可用于容器监控。</p><h3 id="在-portainer-中管理容器镜像" tabindex="-1">在 Portainer 中管理容器镜像 <a class="header-anchor" href="#在-portainer-中管理容器镜像" aria-label="Permalink to “在 Portainer 中管理容器镜像”">​</a></h3><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Endpoints-1024x252.jpg" alt="Portainer-Endpoints"></p><p>检查当前的状态，可以看到有两个容器已经在运行了，如果你创建另一个也会立即显示出来。</p><p>像下面这样，在命令行中启动一个或两个容器，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker run --name test -it debian</span></span>
<span class="line"><span>Unable to find image &#39;debian:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/debian</span></span>
<span class="line"><span>e79bb959ec00: Pull complete</span></span>
<span class="line"><span>Digest: sha256:724b0fbbda7fda6372ffed586670573c59e07a48c86d606bab05db118abe0ef5</span></span>
<span class="line"><span>Status: Downloaded newer image for debian:latest</span></span>
<span class="line"><span>root@linuxtechi:/#</span></span></code></pre></div><p>然后在 Portainer 页面中点击刷新按钮（会出现一条让你确认的消息，点击上面的 “Continue”），就可以像下面高亮显示的一样看到 3 个容器了。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-new-container-image-1024x544.jpg" alt="Portainer-io-new-container-image"></p><p>点击上图中红圈圈出来的 “containers”，下一个页面会显示 “Dashboard Endpoint summary”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-io-Docker-Container-Dash-1024x544.jpg" alt="Portainer-io-Docker-Container-Dash"></p><p>在这个页面中，点击上图高亮和红圈圈出来的 “Containers”，就可以对容器进行监控了。</p><h3 id="以简单的方式对容器进行监控" tabindex="-1">以简单的方式对容器进行监控 <a class="header-anchor" href="#以简单的方式对容器进行监控" aria-label="Permalink to “以简单的方式对容器进行监控”">​</a></h3><p>继续上面的步骤，就会出现一个如下所示精致、漂亮的 “Container list” 页面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-Container-List-1024x538.jpg" alt="Portainer-Container-List"></p><p>所有的容器都可以在这里进行控制（停止、启动等等）。</p><p>1、在这个页面上，停止我们之前启动的 “test” 容器（这是一个我们早先启动的 debian 容器）。</p><p>选中此容器前面的复选框，然后点击上面的“Stop”按钮来停止。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Stop-Container-Portainer-io-dashboard-1024x447.jpg" alt="Stop-Container-Portainer-io-dashboard"></p><p>在命令行中，你也会看到这个容器现在已经停止或退出了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi:~$ sudo docker container ls -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND             CREATED             STATUS                       PORTS                    NAMES</span></span>
<span class="line"><span>d45902e717c0        debian                &quot;bash&quot;              21 minutes ago      Exited (0) 49 seconds ago                             test</span></span>
<span class="line"><span>08b96eddbae9        centos:7              &quot;/bin/bash&quot;         About an hour ago   Exited (137) 9 minutes ago                            mycontainer2</span></span>
<span class="line"><span>35286de9f2e2        portainer/portainer   &quot;/portainer&quot;        2 hours ago         Up About an hour             0.0.0.0:9000-&gt;9000/tcp   compassionate_benz</span></span>
<span class="line"><span>root@linuxtechi:~$</span></span></code></pre></div><p>2、现在，在 Portainer 页面中启动已经停止的两个容器（test 和 mycontainer2）</p><p>选中已停止的这两个容器前面的复选框，然后点击 “Start”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Start-Containers-Portainer-GUI-1024x449.jpg" alt="Start-Containers-Portainer-GUI"></p><p>你会立即看到两条窗口提醒，内容是“容器成功启动”，并且两个容器的状态变为正在运行。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Conatiner-Started-successfully-Portainer-GUI-1024x538.jpg" alt="Conatiner-Started-successfully-Portainer-GUI"></p><h3 id="一步步探索其他多种选项和特性" tabindex="-1">一步步探索其他多种选项和特性 <a class="header-anchor" href="#一步步探索其他多种选项和特性" aria-label="Permalink to “一步步探索其他多种选项和特性”">​</a></h3><p>1、点击高亮的“Images”，你会看到如下页面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Docker-Container-Images-Portainer-GUI-1024x544.jpg" alt="Docker-Container-Images-Portainer-GUI"></p><p>这是可用的容器列表，其中一些可能没在运行。这些容器可以被导入、导出或者上传到不同的位置，截图如下所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Upload-Docker-Container-Image-Portainer-GUI-1024x544.jpg" alt="Upload-Docker-Container-Image-Portainer-GUI"></p><p>2、点击高亮的“Volumes”，显示如下页面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-list-Portainer-io-gui-1024x544.jpg" alt="Volume-list-Portainer-io-gui"></p><p>3、通过下面的操作，可以很容易的添加卷。点击添加卷按钮，出现如下页面，在名称输入框中输入卷名称，例如 “myvol”，然后点击 “Create the volume” 按钮：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-Creation-Portainer-io-gui-1024x544.jpg" alt="Volume-Creation-Portainer-io-gui"></p><p>新创建的卷如下所示（状态为未使用）：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Volume-unused-Portainer-io-gui-1024x544.jpg" alt="Volume-unused-Portainer-io-gui"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>通过上面的安装步骤，你可以到配置和使用 Portainer.io 的多种选项是多么简单和精美，它提供了用于构建和监控 Docker 容器的多种功能和选项。如前所述，这个一个非常轻量的工具，因此不会给主机系统增加任何负担。下一组选项将在本系列的第 2 部分中进行探讨。</p>`,55)),o("p",null,[a[3]||(a[3]=n("另请阅读: ",-1)),e(t,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/"},{default:i(()=>[...a[2]||(a[2]=[n("用 Portainer.io 来监控和管理 Docker 容器（2）",-1)])]),_:1})]),a[21]||(a[21]=o("hr",null,null,-1)),o("p",null,[a[5]||(a[5]=n("via: ",-1)),e(t,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-part1/"},{default:i(()=>[...a[4]||(a[4]=[n("https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-part1/",-1)])]),_:1})]),o("p",null,[a[10]||(a[10]=n("作者：",-1)),e(t,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:i(()=>[...a[6]||(a[6]=[n("Shashidhar Soppin",-1)])]),_:1}),a[11]||(a[11]=n(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...a[7]||(a[7]=[n("lujun9972",-1)])]),_:1}),a[12]||(a[12]=n(" 译者：",-1)),e(t,{href:"https://github.com/jlztan"},{default:i(()=>[...a[8]||(a[8]=[n("jlztan",-1)])]),_:1}),a[13]||(a[13]=n(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[9]||(a[9]=[n("wxy",-1)])]),_:1})]),o("p",null,[a[16]||(a[16]=n("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[14]||(a[14]=[n("LCTT",-1)])]),_:1}),a[17]||(a[17]=n(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[15]||(a[15]=[n("Linux中国",-1)])]),_:1}),a[18]||(a[18]=n(" 荣誉推出",-1))])])}const f=r(d,[["render",u]]);export{x as __pageData,f as default};
